Add form validation to this contact form (name required, valid email, message min 20 chars) with MUI helperText errors, and disable Send until valid:
```jsx
import { useState } from 'react';
import { Stack, TextField, Button } from '@mui/material';
export default function Contact() {
  const [f, setF] = useState({ name: '', email: '', message: '' });
  return <Stack spacing={2}><TextField label="Name" value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} /><TextField label="Email" value={f.email} onChange={(e) => setF({ ...f, email: e.target.value })} /><TextField label="Message" multiline value={f.message} onChange={(e) => setF({ ...f, message: e.target.value })} /><Button variant="contained">Send</Button></Stack>;
}
```
